insert into public.experiences (company,timeframe,role_vi,role_en,achievements_vi,achievements_en,sort_order) values ('VietNam National Construction Consultants (VNCC)','2022 – Present (Ha Noi)','Chuyên gia Revit – Điều phối viên BIM – Quản lý BIM','Revit Specialist – BIM Coordinator – BIM Manager',ARRAY['Đảm nhận vai trò điều phối viên BIM trong nhiều dự án quy mô lớn, chịu trách nhiệm kiểm soát chất lượng mô hình và phối hợp các bộ môn.','Đóng góp xây dựng Kế hoạch Thi hành BIM (BEP) cho Cảng hàng không quốc tế Long Thành.','Tham gia quản lý chiến lược BIM, phát triển nhóm R&D, cải thiện quy trình thiết kế số và tiêu chuẩn BIM. Tổ chức đào tạo Revit nội bộ.']::text[],ARRAY['Served as BIM Coordinator on large-scale projects, responsible for model quality control and interdisciplinary coordination.','Contributed to the BIM Execution Plan (BEP) for Long Thanh International Airport.','Participated in BIM strategy management and developed the office''s R&D team, improving digital design workflows and BIM standards. Conducted internal Revit training.']::text[],2);
insert into public.experiences (company,timeframe,role_vi,role_en,achievements_vi,achievements_en,sort_order) values ('DLLC Urban Development & Architectural Design Consultant','2021 – 2022 (Ha Noi)','KTS Concept','Conceptual Architect',ARRAY['Khởi xướng và phát triển ý tưởng thiết kế cho các cơ sở giáo dục và dự án quy hoạch đô thị.','Tham gia giai đoạn phát triển ý tưởng của một dự án quy hoạch tổng thể cùng Nikken Sekkei.']::text[],ARRAY['Initiated and developed design concepts for educational facilities and urban planning projects.','Participated in the concept development phase of a master planning project with Nikken Sekkei.']::text[],1);
insert into public.experiences (company,timeframe,role_vi,role_en,achievements_vi,achievements_en,sort_order) values ('EBROS C&T VIET NAM Joint Stock Company','2019 – 2021 (Ha Noi)','Thực tập – Triển khai – KTS Concept','Internship – Drafting – Concept',ARRAY['Thiết kế và phát triển ý tưởng cho các dự án quy mô nhỏ, bao gồm không gian thờ cúng tâm linh.','Tạo thiết kế nội thất cho không gian nhà ở và render ở các góc nhìn nội/ngoại thất.']::text[],ARRAY['Designed and developed concepts for small-scale projects, including spiritual worship spaces.','Created interior designs for residential spaces and rendered interior/exterior views.']::text[],0);
