insert into public.projects (slug,title_vi,title_en,construction_class_vi,construction_class_en,location_vi,location_en,primary_role_vi,primary_role_en,overview_vi,overview_en,responsibilities_vi,responsibilities_en,sort_order) values ('xuan-dai-bay','Tổ hợp du lịch nghỉ dưỡng Xuân Đài Bay','Xuan Dai Bay resort and tourism Complex','Cấp công trình: II','Construction Class: II','Phú Yên, Việt Nam','Phu Yen, Viet Nam','Triển khai chính','Main deployment','Thông tin dự án theo CV (Kinh nghiệm – Vai trò chính).','Project information follows the CV (Experience – Primary Role).',ARRAY['Triển khai hồ sơ kiến trúc (bản vẽ chi tiết) và phối hợp các bên liên quan.','Thực hiện phối cảnh / render phục vụ trình bày.']::text[],ARRAY['Prepared architectural deliverables (detailed drawings) and coordinated with stakeholders.','Produced render/perspective views for presentation.']::text[],0);
insert into public.projects (slug,title_vi,title_en,construction_class_vi,construction_class_en,location_vi,location_en,primary_role_vi,primary_role_en,overview_vi,overview_en,responsibilities_vi,responsibilities_en,sort_order) values ('vung-lam-phu-yen','Khu nghỉ dưỡng Vũng Lâm Phú Yên','Vung Lam Phu Yen resort','Cấp công trình: I','Construction Class: I','Phú Yên, Việt Nam','Phu Yen, Viet Nam','Triển khai chính','Main deployment','Vai trò tập trung vào điều phối BIM và triển khai hồ sơ theo CV.','Role focused on BIM coordination and deliverables, as described in the CV.',ARRAY['Điều phối BIM, kiểm soát chất lượng mô hình và phối hợp liên bộ môn.','Tham gia xây dựng / triển khai BEP (BIM Execution Plan) theo yêu cầu dự án.','Chuẩn hóa quy trình BIM và hỗ trợ đào tạo nội bộ.','Triển khai hồ sơ kiến trúc (bản vẽ chi tiết) và phối hợp các bên liên quan.','Thực hiện phối cảnh / render phục vụ trình bày.']::text[],ARRAY['BIM coordination, model quality control, and interdisciplinary coordination.','Contributed to / implemented the BIM Execution Plan (BEP) per project requirements.','Improved BIM standards and supported internal training.','Prepared architectural deliverables (detailed drawings) and coordinated with stakeholders.','Produced render/perspective views for presentation.']::text[],1);
